"""No square Mochi popups (user 2026-10-16 "how ugly it is"). Feed reacts in the Home scene via crossfade; missions confirm inline;
the toast always sits above the swipe pill and the bar. Usage: no_popups.py [base_url] [shots_dir]"""
import sys, os
from playwright.sync_api import sync_playwright
U = sys.argv[1] if len(sys.argv) > 1 else 'http://localhost:8897/platform-app-v2.html'
SH = sys.argv[2] if len(sys.argv) > 2 else '/workspace/hana-shots/no-popups'; os.makedirs(SH, exist_ok=True)
R = []; ok = lambda n, c, d='': (R.append(bool(c)), print(('PASS ' if c else 'FAIL ') + n + ('' if c else f' :: {str(d)[:300]}')))
FRESH = "()=>{const dk=dayKey(ME,PV.now());delete ME.days[dk];P2S.dm=null;P2S.cat={};ST.miss.rest=false;ST.catEat=false;ST.catReact=null;CH.cici.gate=false;ME.streak=12;ME.paused=false;P2S.cat.demoHour=18;P2S.cat.treats=1;CAT_ROOM.eat=false;closeSheet();render()}"  # petting path; the eat path is covered by feed_eat.py
WATCH = "()=>{window.__pop=0;new MutationObserver(()=>{if(document.querySelector('#cat-clip,#cat-eat,.cateat,.catclip,.cateatx'))window.__pop++}).observe(document.body,{childList:true,subtree:true})}"
RECT = "s=>{const e=document.querySelector(s);if(!e||e.hidden)return null;const r=e.getBoundingClientRect();return [r.top,r.bottom,r.left,r.right]}"
with sync_playwright() as p:
  b = p.chromium.launch()
  for w, h in [(390, 844), (430, 932)]:
    for L in ('en', 'ko'):
      c = b.new_context(viewport={'width': w, 'height': h}); g = c.new_page(); E = []; g.on('pageerror', lambda e: E.append(str(e)))
      q = '?phase2=1'; g.goto(U + q); g.evaluate('localStorage.clear()'); g.goto(U + q); g.wait_for_timeout(400)
      J = g.evaluate; J(f"()=>{{setLang('{L}');ST.tab='home';ST.page=null;render()}}"); J(FRESH); J(WATCH); g.wait_for_timeout(900)
      tag = f'{L}-{w}'
      g.screenshot(path=f'{SH}/home-before-feed-{tag}.png'); g.screenshot(path=f'{SH}/hungry-room-bounce-{tag}.png')
      ok(f'[{tag}] hungry room: Cici+Mochi room loop (no kitten close-up), empty-bowl cue, Feed bouncing', J("catMood()==='hungry' && (document.querySelector('.catvid.on')||{}).dataset.clip===(CAT_ROOM.hungry?'room-hungry':'petting') && !!document.querySelector('#cat-feed #cat-room-bowl') && document.querySelector('#cat-feed').dataset.state==='hungry' && getComputedStyle(document.querySelector('#cat-feed')).animationName==='fabpulse'"))
      ok(f'[{tag}] card shows missions and the next class', J("/\\d\\/3/.test(document.querySelector('#hb-bubble').textContent) && (!upcoming()[0] || !!document.querySelector('#v2-next,#v2-mis'))"))
      ok(f'[{tag}] Feed button is big and round with fish + count badge', J("(()=>{const e=document.querySelector('#cat-feed');const r=e.getBoundingClientRect();return r.width>=44&&r.width<=60&&e.textContent.includes('🐟')&&e.querySelector('.catbadge').textContent==='1'})()"))
      ok(f'[{tag}] action circles: ≤4, ≥12px above the bar, 44-56px, captioned, labelled', (lambda a, z: a and z and z[0] - a[1] >= 12)(J(RECT, '#v2-acts'), J(RECT, 'nav.tabs')) and J("(()=>{const c=[...document.querySelectorAll('#v2-acts .catfab')];return c.length>=2&&c.length<=4&&c.every(b=>{const r=b.getBoundingClientRect();return r.width>=44&&r.width<=60&&b.getAttribute('aria-label')&&b.parentElement.querySelector('.v2cap')})})()"), [J(RECT, '#v2-acts'), J(RECT, 'nav.tabs')])
      ok(f'[{tag}] no swipe pill; Missions circle opens the Today sheet', J("!document.querySelector('.v2pull,.v2handle') && document.querySelector('#v2-pull').dataset.act==='hbsheet'"))
      ok(f'[{tag}] Home card: greeting + next class + missions count only', J("(()=>{const c=document.querySelector('#hb-bubble');return !!c.querySelector('.hbhi')&&/\\d\\/3/.test(c.textContent)&&!c.querySelector('.dmbar,.gtrack,progress')})()"))
      ok(f'[{tag}] feed button ≥44px', J("(()=>{const r=document.querySelector('#cat-feed').getBoundingClientRect();return r.width>=44&&r.height>=44})()"))
      J("()=>{window.__vib=0;navigator.vibrate=()=>{window.__vib++;return true}}")
      J("()=>document.querySelector('#cat-feed').click()"); g.wait_for_timeout(230)
      ok(f'[{tag}] mid-feed: fish in flight, squish, haptic, badge ticked down', J("!!document.querySelector('#cat-fish') && !!document.querySelector('.catfab.squish') && window.__vib>0 && document.querySelector('#cat-fab-empty .catbadge').textContent==='0'"))
      g.screenshot(path=f'{SH}/mid-feed-fish-{tag}.png')
      mid = J("[...document.querySelectorAll('#cici-real .catvid')].map(v=>[v.dataset.clip,+getComputedStyle(v).opacity])")
      g.screenshot(path=f'{SH}/home-feed-midfade-{tag}.png')
      ok(f'[{tag}] feed: smooth crossfade in progress (two clips, partial opacity)', any(0 < o < 1 for _, o in mid) or len(mid) == 2, mid)
      g.screenshot(path=f'{SH}/toast-{tag}.png')
      t, pl, nv = J(RECT, '#toast'), J(RECT, '#v2-acts'), J(RECT, 'nav.tabs')
      ok(f'[{tag}] toast visible and does not overlap the circles or the bar', t and pl and nv and (t[3] <= pl[2] or t[1] <= pl[0]) and t[1] <= nv[0], [t, pl, nv])
      ok(f'[{tag}] toast on top (elementFromPoint at its centre)', J("(()=>{const r=document.querySelector('#toast').getBoundingClientRect();const e=document.elementFromPoint(r.left+r.width/2,r.top+r.height/2);return !!e&&!!e.closest('#toast')})()"))
      g.wait_for_timeout(600)
      ok(f'[{tag}] after the fish: Cici pets Mochi (petting clip, card says petting)', J("(document.querySelector('.catvid.on')||{}).dataset.clip==='petting' && /pet|vuốt|쓰다듬/i.test(document.querySelector('#cat-line').textContent)"), J("[(document.querySelector('.catvid.on')||{}).dataset.clip,(document.querySelector('#cat-line')||{}).textContent]"))
      g.screenshot(path=f'{SH}/petting-after-feed-{tag}.png')
      g.wait_for_timeout(2400)
      ok(f'[{tag}] fed from hungry -> playful: lively clip, card says playful, bowl gone, no dim', J("(document.querySelector('.catvid.on')||{}).dataset.clip===(CAT_ROOM.happy?'room-happy':'lively') && !catHungry() && catDay().treats===0 && /playful|vui|신나/.test(document.querySelector('#cat-line').textContent) && !document.querySelector('#cat-room-bowl') && !document.querySelector('.sheet-bg')"), J("[(document.querySelector('.catvid.on')||{}).dataset.clip, (document.querySelector('#cat-line')||{}).textContent]"))
      g.screenshot(path=f'{SH}/playful-after-{tag}.png')
      g.wait_for_timeout(3000)
      ok(f'[{tag}] feed: crossfaded back to mood loop', J("(document.querySelector('.catvid.on')||{}).dataset.clip===catClipName(catMood()) && catMood()!=='eating'"))
      g.screenshot(path=f'{SH}/home-after-feed-{tag}.png')
      ok(f'[{tag}] empty state: gentle button, not dead', J("(()=>{const e=document.querySelector('#cat-fab-empty');return !!e&&e.dataset.state==='empty'&&!e.disabled&&getComputedStyle(e).animationName!=='fabpulse'})()"))
      g.screenshot(path=f'{SH}/empty-state-{tag}.png')
      J("()=>document.querySelector('#cat-fab-empty').click()"); g.wait_for_timeout(400)
      ok(f'[{tag}] empty tap: nudge toast + missions open', J("!!document.querySelector('.sheet #home-dm') && /mission|nhiệm|미션/i.test(document.querySelector('#toast').textContent)"))
      J("()=>closeSheet()"); g.wait_for_timeout(200)
      J("()=>{P2S.cat.treats=2;P2S.cat.demoHour=12;render()}"); g.wait_for_timeout(200)
      ok(f'[{tag}] ready state (treats, not hungry): no bounce', J("document.querySelector('#cat-feed').dataset.state==='ready' && getComputedStyle(document.querySelector('#cat-feed')).animationName!=='fabpulse'"))
      J("()=>{P2S.cat.treats=0;render()}")
      ok(f'[{tag}] Home stays non-scrollable', J("Math.abs(document.documentElement.scrollHeight-document.documentElement.clientHeight)<=2"))
      J("()=>openHomeSheet()"); g.wait_for_timeout(300); J("()=>document.querySelector('[data-act=dmwater]').click()"); g.wait_for_timeout(700)
      ok(f'[{tag}] water Done: sheet closes, room loop stays, water clip in a small round PiP bubble (no dim, no X)', J("!document.querySelector('.sheet') && (CAT_ROOM.water ? ((document.querySelector('.catvid.on')||{}).dataset.clip==='room-water'&&!document.querySelector('#cat-pip')&&!document.querySelector('.sheet-bg')) : (()=>{const o=document.querySelector('#cat-pip[data-kind=water]');if(!o)return false;const r=o.getBoundingClientRect();return r.width>=96&&r.width<=120&&!o.querySelector('button')&&(document.querySelector('.catvid.on')||{}).dataset.clip!=='water'&&!document.querySelector('.sheet-bg')})()) && /bowl|bát|그릇|sipping|uống|물/.test(document.querySelector('#cat-line').textContent)"), J("[!!document.querySelector('.sheet'),(document.querySelector('.catvid.on')||{}).dataset.clip]"))
      g.screenshot(path=f'{SH}/room-water-{tag}.png')
      ok(f'[{tag}] ONE message after the mission: single toast with points + Mochi + treat, no win card', J("(()=>{const t=document.querySelector('#toast'),w=document.querySelector('#wintoast');return !t.hidden&&/\\+10/.test(t.textContent)&&/(drank|sipped|uống|물)/.test(t.textContent)&&(!w||w.hidden)&&!document.querySelector('.confetti')})()"), J("[document.querySelector('#toast').textContent,!!document.querySelector('#wintoast:not([hidden])')]"))
      g.screenshot(path=f'{SH}/mission-toast-{tag}.png')
      ok(f'[{tag}] PiP bubble clear of the action circles and the card', J("(()=>{const p=document.querySelector('#cat-pip');if(!p)return CAT_ROOM.water;const o=p.getBoundingClientRect(),a=document.querySelector('#v2-acts').getBoundingClientRect(),c=document.querySelector('#hb-bubble').getBoundingClientRect();return o.right<a.left&&o.top>c.bottom})()"))
      g.wait_for_timeout(4200)
      ok(f'[{tag}] water bubble fades out, room loop continues', J("!ST.catMis && !document.querySelector('#cat-pip') && (document.querySelector('.catvid.on')||{}).dataset.clip===catClipName(catMood())"))
      J("()=>openHomeSheet()"); g.wait_for_timeout(500)
      g.screenshot(path=f'{SH}/sheet-after-water-{tag}.png')
      ok(f'[{tag}] water Done: inline Mochi line in the row', J("!!document.querySelector('#home-dm .mis[data-m=water].done .misok')"))
      ok(f'[{tag}] sheet toast does not cover the ticked row', J("(()=>{const b=document.querySelector('#home-dm .mis[data-m=water] .misok').getBoundingClientRect();return ['#toast','#wintoast'].every(q=>{const t=document.querySelector(q);if(!t||t.hidden||getComputedStyle(t).visibility==='hidden')return true;const a=t.getBoundingClientRect();return a.bottom<=b.top||a.top>=b.bottom})})()"))
      tt = J(RECT, '#toast'), J(RECT, 'nav.tabs')
      ok(f'[{tag}] sheet toast on top and clear of the bar', J("(()=>{const e=document.querySelector('#toast');if(e.hidden)return true;const r=e.getBoundingClientRect();const x=document.elementFromPoint(r.left+r.width/2,r.top+r.height/2);return !!x&&!!x.closest('#toast')})()") and (not tt[0] or tt[0][1] <= tt[1][0]), tt)
      J("()=>{closeSheet();stretchSheet()}"); g.wait_for_timeout(700)
      ok(f'[{tag}] stretch: room loop + stretch PiP bubble + small glass timer chip (no sheet)', J("!document.querySelector('.sheet') && !!document.querySelector('#v2-hero #stretch-chip #stl') && (CAT_ROOM.stretch ? ((document.querySelector('.catvid.on')||{}).dataset.clip==='room-stretch'&&!document.querySelector('#cat-pip')&&!document.querySelector('.sheet-bg')) : (()=>{const o=document.querySelector('#cat-pip[data-kind=stretch]');if(!o)return false;const r=o.getBoundingClientRect();return r.width>=96&&r.width<=120&&!o.querySelector('button')&&(document.querySelector('.catvid.on')||{}).dataset.clip!=='stretch'&&!document.querySelector('.sheet-bg')})())"))
      ok(f'[{tag}] stretch chip buttons ≥44px and clear of the bar', J("(()=>{const c=document.querySelector('#stretch-chip').getBoundingClientRect(),p=document.querySelector('nav.tabs').getBoundingClientRect();return [...document.querySelectorAll('#stretch-chip button')].every(b=>b.getBoundingClientRect().height>=44)&&c.bottom<=p.top})()"))
      g.screenshot(path=f'{SH}/room-stretch-chip-{tag}.png')
      J("()=>document.querySelector('#stretch-chip [data-act=stretchdone]').click()"); g.wait_for_timeout(700)
      ok(f'[{tag}] stretch Finish: chip + bubble gone, mission ticked', J("!document.querySelector('#stretch-chip') && !document.querySelector('#cat-pip.on') && !ST.catMis && dmDay().done.stretch && (document.querySelector('.catvid.on')||{}).dataset.clip===catClipName(catMood())"))
      ok(f'[{tag}] no #cat-clip / square popup ever appeared', J("window.__pop===0"), J("window.__pop"))
      J("()=>{crisisReply(CH.cici,'x');render()}")
      ok(f'[{tag}] crisis hides feed/hunger', J("!document.querySelector('.catfab') && !catHungry()"))
      ok(f'[{tag}] no page errors', not E, E); c.close()
  # reduced motion: still image, feed still works without popup
  c = b.new_context(viewport={'width': 390, 'height': 844}, reduced_motion='reduce'); g = c.new_page()
  g.goto(U + '?phase2=1'); g.evaluate('localStorage.clear()'); g.goto(U + '?phase2=1'); g.wait_for_timeout(400)
  g.evaluate("()=>{setLang('en');ST.tab='home';render()}"); g.evaluate(FRESH); g.evaluate(WATCH); g.wait_for_timeout(300)
  g.evaluate("()=>document.querySelector('#cat-feed').click()"); g.wait_for_timeout(400)
  ok('reduced motion: still image, no video, no popup', g.evaluate("!!document.querySelector('#cici-real img.catstill') && !document.querySelector('#cici-real video') && !document.querySelector('#cat-fish') && window.__pop===0 && catDay().treats===0"))
  ok('room clip map: tall room clips absent -> fallbacks; present -> used', g.evaluate("(()=>{const off=!CAT_ROOM.hungry&&!CAT_ROOM.water&&catClipName('hungry')==='petting';CAT_ROOM.hungry=true;CAT_ROOM.happy=true;const on=catClipName('hungry')==='room-hungry'&&catClipSrc('room-water').mp4==='assets/cici-real/cici-room-water_tall.mp4'&&catClipSrc('room-stretch').webm==='assets/cici-real/cici-room-stretch_tall.webm'&&(catDay().fed>0?catClipName('lively')==='room-happy':true);CAT_ROOM.hungry=false;CAT_ROOM.happy=false;return off&&on})()"))
  c.close(); b.close()
  print(f'{sum(R)}/{len(R)}'); sys.exit(0 if all(R) else 1)
